import xml.etree.ElementTree as ET
from collections import defaultdict
path='/tmp/weo_sdmx/WEOAPR2025/xmlfile_APR2025.xml'

def to_float(val):
    try:
        return float(val)
    except (TypeError, ValueError):
        return None

series_data=defaultdict(dict)
wanted={'NGDP_R','NGDP_RPCH'}
for event, elem in ET.iterparse(path, events=('end',)):
    if elem.tag.endswith('Series'):
        ref_area=elem.attrib.get('REF_AREA')
        concept=elem.attrib.get('CONCEPT')
        if ref_area=='915' and concept in wanted:
            data={}
            for obs in elem:
                if obs.tag.endswith('Obs'):
                    year=obs.attrib.get('TIME_PERIOD')
                    val=to_float(obs.attrib.get('OBS_VALUE'))
                    data[int(year)]=val
            series_data[concept]=data
        elem.clear()

print('found', series_data.keys())
for concept in wanted:
    data=series_data.get(concept, {})
    years=sorted(data)
    print(concept, years[:3], years[-3:])
    print('2000', data.get(2000), '2027', data.get(2027))
PY"}

