import xml.etree.ElementTree as ET
path='/tmp/ecb_cfc.csv'
# parse
ns={'gen':'http://www.sdmx.org/resources/sdmxml/schemas/v2_1/data/generic'}
# iterparse to get Obs
values={}
for event, elem in ET.iterparse(path, events=('end',)):
    if elem.tag.endswith('Obs'):
        time=None; value=None
        for child in elem:
            if child.tag.endswith('ObsDimension'):
                time=child.attrib.get('value')
            elif child.tag.endswith('ObsValue'):
                value=child.attrib.get('value')
        if time:
            try:
                values[int(time)]=float(value) if value not in (None,'') else None
            except ValueError:
                values[int(time)]=None
        elem.clear()

print('years', min(values), max(values), 'count', len(values))
print('sample', {y: values[y] for y in range(2018,2024)})
PY"}
